pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok = true;
        try c.setOwner(newOwner) returns (bool success) {
            assertTrue(success && c.owner() == newOwner && actor == address(this));
        } catch {
            ok = false;
            assertTrue(!ok && c.owner() != newOwner);
        }
    }
}

